package com.srinu.otelpoc.customer.api; import com.srinu.otelpoc.customer.domain.Customer; import com.srinu.otelpoc.customer.service.CustomerApplicationService; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/customers") public class CustomerController { private final CustomerApplicationService service; public CustomerController(CustomerApplicationService s){service=s;} @GetMapping public List<Customer> list(){return service.list();} @GetMapping("/{id}") public Customer get(@PathVariable String id){return service.get(id);} @PostMapping public ResponseEntity<Customer> create(@Valid @RequestBody CustomerRequest r){var c=new Customer(UUID.randomUUID().toString(),r.name(),r.email(),r.accountNumber()); return ResponseEntity.status(201).body(service.create(c));} @PutMapping("/{id}") public Customer update(@PathVariable String id,@Valid @RequestBody CustomerRequest r){return service.update(id,r.name(),r.email(),r.accountNumber());} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deactivate(@PathVariable String id){service.deactivate(id);} public record CustomerRequest(@NotBlank String name,@Email @NotBlank String email,@NotBlank String accountNumber){} }
